  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(payload).digest('hex')
  return crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))
}

function hasBugLabel(labels: Array<{ name: string }>): boolean {
  return labels.some((label) => label.name === 'bug')
}

export async function handle(
  payload: GitHubIssuePayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.action || payload.action !== 'labeled') {
    throw new Error('Invalid payload: action must be "labeled"')
  }

  if (!payload.issue) {
    throw new Error('Invalid payload: missing issue object')
  }

  if (!payload.issue.title) {
    throw new Error('Invalid payload: issue.title is required')
  }

  if (payload.issue.body === undefined || payload.issue.body === null) {
    throw new Error('Invalid payload: issue.body is required')
  }

  if (!payload.issue.html_url) {
    throw new Error('Invalid payload: issue.html_url is required')
  }

  if (!payload.issue.labels || !Array.isArray(payload.issue.labels) || payload.issue.labels.length === 0) {
    throw new Error('Invalid payload: issue.labels is required and must not be empty')
  }

  if (!hasBugLabel(payload.issue.labels)) {
    throw new Error('Invalid payload: issue must have label "bug"')
  }

  if (!config.linearTriageTeamId) {
    throw new Error('Configuration error: linearTriageTeamId is required')
  }

  const title = payload.issue.title
  const description = `${payload.issue.body}\n\n---\nSource: ${payload.issue.html_url}`

  const graphqlMutation = `
    mutation IssueCreate {
      issueCreate(input: {
        title: ${JSON.stringify(title)},
        description: ${JSON.stringify(description)},
        teamId: ${JSON.stringify(config.linearTriageTeamId)}
      }) {
        success
        issue {
          id
          title
        }
      }
    }
  `.trim()

  const response = await fetchImpl('https://api.linear.app/graphql', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${config.linearApiKey}`,
    },
    body: JSON.stringify({ query: graphqlMutation }),
  })

  if (!response.ok) {
    throw new Error(`Linear API error: ${response.status} ${response.statusText} at POST https://api.linear.app/graphql`)
  }

  const data = (await response.json()) as {
    data?: {
      issueCreate?: {
        success: boolean
        issue?: { id: string; title: string }
      }
    }
    errors?: Array<{ message: string }>
  }

  if (data.errors && data.errors.length > 0) {
    throw new Error(`Linear API error: ${data.errors.map((e) => e.message).join(', ')}`)
  }

  if (!data.data?.issueCreate?.success || !data.data.issueCreate.issue) {
    throw new Error('Linear API error: issue creation failed')
  }

  return {
    linearIssueId: data.data.issueCreate.issue.id,
    linearIssueTitle: data.data.issueCreate.issue.title,
  }
}

